html:
{% set company = frappe.get_doc('Company', doc.company) %}
{% set address = frappe.get_doc('Address', doc.company_address) if doc.company_address else none %}
{% set supplier_addr = frappe.get_doc('Address', doc.supplier_address) if doc.supplier_address else none %}

<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head>
<meta charset="UTF-8">
<style>
  @import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700&family=Tajawal:wght@400;500;700&display=swap');

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: 'Cairo', 'Tajawal', Arial, sans-serif;
    font-size: 13px;
    color: #171717;
    direction: rtl;
    background: #fff;
  }

  .wrapper { padding: 8px; }

  /* ===== HEADER ===== */
  .header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    padding-bottom: 10px;
    border-bottom: 2px solid #171717;
    margin-bottom: 10px;
  }
  .company-info { flex: 1; }
  .company-name {
    font-size: 20px;
    font-weight: 700;
    color: #171717;
    line-height: 1.2;
  }
  .company-sub {
    font-size: 11px;
    color: #525252;
    margin-top: 2px;
  }
  .company-details {
    font-size: 11px;
    color: #525252;
    margin-top: 4px;
    line-height: 1.6;
  }
  .logo-area { text-align: left; }
  .logo-area img { max-height: 70px; max-width: 140px; object-fit: contain; }

  /* ===== INVOICE TITLE ===== */
  .invoice-title {
    text-align: center;
    margin: 10px 0;
    padding: 6px 0;
    border-top: 1px solid #ededed;
    border-bottom: 1px solid #ededed;
  }
  .invoice-title .ar { font-size: 18px; font-weight: 700; letter-spacing: 1px; }
  .invoice-title .en { font-size: 11px; color: #525252; letter-spacing: 2px; text-transform: uppercase; }

  /* ===== STAMPS ===== */
  .draft-stamp, .cancelled-stamp {
    position: fixed;
    top: 40%;
    left: 50%;
    transform: translate(-50%, -50%) rotate(-30deg);
    font-size: 72px;
    font-weight: 900;
    opacity: 0.08;
    pointer-events: none;
    z-index: 999;
  }
  .draft-stamp { color: #888; }
  .cancelled-stamp { color: #c00; }

  /* ===== META GRID ===== */
  .meta-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    margin-bottom: 10px;
  }
  .meta-box {
    border: 1px solid #ededed;
    border-radius: 4px;
    padding: 8px 10px;
    background: #f8f8f8;
  }
  .meta-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    padding: 3px 0;
    border-bottom: 1px dotted #e0e0e0;
  }
  .meta-row:last-child { border-bottom: none; }
  .meta-label .ar { font-weight: 600; font-size: 12px; }
  .meta-label .en { font-size: 9px; color: #525252; display: block; line-height: 1; }
  .meta-value { font-weight: 600; font-size: 12px; text-align: left; direction: ltr; }

  /* ===== ADDRESS BOXES ===== */
  .address-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    margin-bottom: 10px;
  }
  .address-box {
    border: 1px solid #ededed;
    border-radius: 4px;
    padding: 8px 10px;
  }
  .address-box .box-title {
    font-size: 11px;
    font-weight: 700;
    color: #525252;
    border-bottom: 1px solid #ededed;
    padding-bottom: 4px;
    margin-bottom: 6px;
  }
  .address-box .box-title .en { font-size: 9px; }
  .address-box .party-name { font-size: 13px; font-weight: 700; margin-bottom: 4px; }
  .address-box address {
    font-size: 11px;
    color: #525252;
    line-height: 1.6;
    font-style: normal;
  }

  /* ===== ITEMS TABLE ===== */
  .items-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 10px;
    font-size: 12px;
  }
  .items-table thead tr {
    background: #171717;
    color: #fff;
  }
  .items-table thead th {
    padding: 7px 8px;
    text-align: right;
    font-weight: 600;
  }
  .items-table thead th .en {
    display: block;
    font-size: 9px;
    font-weight: 400;
    opacity: 0.7;
    line-height: 1;
  }
  .items-table thead th.num-col { text-align: center; width: 32px; }
  .items-table thead th.qty-col, .items-table thead th.rate-col, .items-table thead th.amt-col {
    text-align: left;
    width: 80px;
  }
  .items-table tbody tr { border-bottom: 1px solid #ededed; }
  .items-table tbody tr:nth-child(even) { background: #f8f8f8; }
  .items-table tbody td { padding: 7px 8px; vertical-align: top; }
  .items-table tbody td.num-col { text-align: center; color: #525252; }
  .items-table tbody td.qty-col, .items-table tbody td.rate-col, .items-table tbody td.amt-col {
    text-align: left;
    direction: ltr;
    white-space: nowrap;
  }
  .item-name { font-weight: 600; }
  .item-desc { font-size: 10px; color: #525252; margin-top: 2px; }

  /* ===== TOTALS ===== */
  .totals-section {
    display: flex;
    justify-content: space-between;
    gap: 10px;
    margin-bottom: 10px;
    align-items: flex-start;
  }
  .in-words-box {
    flex: 1;
    border: 1px solid #ededed;
    border-radius: 4px;
    padding: 8px 10px;
    background: #f8f8f8;
    font-size: 12px;
  }
  .in-words-box .label .ar { font-weight: 700; font-size: 11px; }
  .in-words-box .label .en { font-size: 9px; color: #525252; }
  .in-words-box .value { margin-top: 4px; font-style: italic; }
  .totals-table { width: 220px; font-size: 12px; }
  .totals-table tr td { padding: 4px 6px; }
  .totals-table tr td:first-child { text-align: right; color: #525252; }
  .totals-table tr td:last-child { text-align: left; direction: ltr; font-weight: 600; white-space: nowrap; }
  .totals-table .grand-total-row td {
    font-size: 14px;
    font-weight: 700;
    border-top: 2px solid #171717;
    padding-top: 6px;
    color: #171717;
  }
  .totals-table .discount-row td { color: #c00; }

  /* ===== TERMS ===== */
  .terms-section {
    border-top: 1px solid #ededed;
    padding-top: 8px;
    margin-top: 4px;
    font-size: 11px;
    color: #525252;
  }
  .terms-section .label { font-weight: 700; color: #171717; margin-bottom: 4px; }
  .terms-section .label .en { font-size: 9px; color: #525252; }

  /* ===== FOOTER ===== */
  .footer {
    margin-top: 10px;
    padding-top: 6px;
    border-top: 1px solid #ededed;
    text-align: center;
    font-size: 10px;
    color: #525252;
  }
</style>
</head>
<body>
<div class="wrapper">

  {%- if doc.docstatus == 0 %}
  <div class="draft-stamp">مسودة</div>
  {%- endif %}
  {%- if doc.docstatus == 2 %}
  <div class="cancelled-stamp">ملغي</div>
  {%- endif %}

  <!-- HEADER -->
  <div class="header">
    <div class="company-info">
      <div class="company-name">{{ doc.company }}</div>
      {%- if company.company_name_in_arabic %}
      <div class="company-sub">{{ company.company_name_in_arabic }}</div>
      {%- endif %}
      <div class="company-details">
        {%- if company.tax_id %}
        <span>الرقم الضريبي: {{ company.tax_id }}</span><br>
        {%- endif %}
        {%- if company.phone_no %}
        <span>{{ company.phone_no }}</span>
        {%- endif %}
      </div>
    </div>
    <div class="logo-area">
      {%- if company.company_logo %}
      <img src="{{ company.company_logo }}" alt="Logo">
      {%- endif %}
    </div>
  </div>

  <!-- INVOICE TITLE -->
  <div class="invoice-title">
    <div class="ar">════ فاتورة مشتريات ════</div>
    <div class="en">PURCHASE INVOICE</div>
  </div>

  <!-- META GRID -->
  <div class="meta-grid">
    <div class="meta-box">
      <div class="meta-row">
        <div class="meta-label"><span class="ar">رقم الفاتورة</span><span class="en">Invoice #</span></div>
        <div class="meta-value">{{ doc.name }}</div>
      </div>
      <div class="meta-row">
        <div class="meta-label"><span class="ar">تاريخ الفاتورة</span><span class="en">Date</span></div>
        <div class="meta-value">{{ doc.posting_date }}</div>
      </div>
      {%- if doc.due_date %}
      <div class="meta-row">
        <div class="meta-label"><span class="ar">تاريخ الاستحقاق</span><span class="en">Due Date</span></div>
        <div class="meta-value">{{ doc.due_date }}</div>
      </div>
      {%- endif %}
      {%- if doc.bill_no %}
      <div class="meta-row">
        <div class="meta-label"><span class="ar">رقم فاتورة المورد</span><span class="en">Supplier Inv. No.</span></div>
        <div class="meta-value">{{ doc.bill_no }}</div>
      </div>
      {%- endif %}
    </div>
    <div class="meta-box">
      <div class="meta-row">
        <div class="meta-label"><span class="ar">اسم المورد</span><span class="en">Supplier</span></div>
        <div class="meta-value">{{ doc.supplier_name or doc.supplier }}</div>
      </div>
      {%- if doc.currency != company.default_currency %}
      <div class="meta-row">
        <div class="meta-label"><span class="ar">العملة</span><span class="en">Currency</span></div>
        <div class="meta-value">{{ doc.currency }}</div>
      </div>
      {%- endif %}
      {%- if doc.payment_terms_template %}
      <div class="meta-row">
        <div class="meta-label"><span class="ar">شروط الدفع</span><span class="en">Payment Terms</span></div>
        <div class="meta-value">{{ doc.payment_terms_template }}</div>
      </div>
      {%- endif %}
    </div>
  </div>

  <!-- ADDRESSES -->
  <div class="address-grid">
    <div class="address-box">
      <div class="box-title">الفوترة إلى <span class="en">/ Bill To (Us)</span></div>
      <div class="party-name">{{ doc.company }}</div>
      <address>
        {%- if address %}
        {%- if address.address_line1 %}{{ address.address_line1 }}<br>{%- endif %}
        {%- if address.address_line2 %}{{ address.address_line2 }}<br>{%- endif %}
        {%- if address.city %}{{ address.city }}{%- if address.state %}, {{ address.state }}{%- endif %}<br>{%- endif %}
        {%- if address.country %}{{ address.country }}{%- endif %}
        {%- else %}
        {%- if company.city %}{{ company.city }}<br>{%- endif %}
        {%- if company.country %}{{ company.country }}{%- endif %}
        {%- endif %}
      </address>
    </div>
    <div class="address-box">
      <div class="box-title">الفوترة من <span class="en">/ Bill From (Supplier)</span></div>
      <div class="party-name">{{ doc.supplier_name or doc.supplier }}</div>
      <address>
        {%- if supplier_addr %}
        {%- if supplier_addr.address_line1 %}{{ supplier_addr.address_line1 }}<br>{%- endif %}
        {%- if supplier_addr.address_line2 %}{{ supplier_addr.address_line2 }}<br>{%- endif %}
        {%- if supplier_addr.city %}{{ supplier_addr.city }}{%- if supplier_addr.state %}, {{ supplier_addr.state }}{%- endif %}<br>{%- endif %}
        {%- if supplier_addr.country %}{{ supplier_addr.country }}{%- endif %}
        {%- endif %}
      </address>
    </div>
  </div>

  <!-- ITEMS TABLE -->
  <table class="items-table">
    <thead>
      <tr>
        <th class="num-col">#</th>
        <th>اسم الصنف <span class="en">Item Name</span></th>
        <th>الوصف <span class="en">Description</span></th>
        <th class="qty-col">الكمية <span class="en">Qty</span></th>
        <th class="rate-col">السعر <span class="en">Rate</span></th>
        <th class="amt-col">المبلغ <span class="en">Amount</span></th>
      </tr>
    </thead>
    <tbody>
      {%- for item in doc.items %}
      <tr>
        <td class="num-col">{{ loop.index }}</td>
        <td>
          <div class="item-name">{{ item.item_name }}</div>
          {%- if item.item_code != item.item_name %}
          <div class="item-desc">{{ item.item_code }}</div>
          {%- endif %}
        </td>
        <td>
          {%- if item.description and item.description != item.item_name %}
          <div class="item-desc">{{ item.description | striptags }}</div>
          {%- endif %}
        </td>
        <td class="qty-col">{{ item.qty }} {{ item.uom }}</td>
        <td class="rate-col">{{ frappe.utils.fmt_money(item.rate, currency=doc.currency) }}</td>
        <td class="amt-col">{{ frappe.utils.fmt_money(item.amount, currency=doc.currency) }}</td>
      </tr>
      {%- endfor %}
    </tbody>
  </table>

  <!-- TOTALS SECTION -->
  <div class="totals-section">
    <div class="in-words-box">
      <div class="label"><span class="ar">المبلغ كتابةً</span> <span class="en">/ Total in Words</span></div>
      <div class="value">{{ doc.in_words or '' }}</div>
    </div>
    <table class="totals-table">
      <tr>
        <td>المجموع الفرعي <small>Sub Total</small></td>
        <td>{{ frappe.utils.fmt_money(doc.total, currency=doc.currency) }}</td>
      </tr>
      {%- if doc.discount_amount and doc.discount_amount > 0 %}
      <tr class="discount-row">
        <td>خصم <small>Discount</small></td>
        <td>-{{ frappe.utils.fmt_money(doc.discount_amount, currency=doc.currency) }}</td>
      </tr>
      {%- endif %}
      {%- for tax in doc.taxes %}
      {%- if tax.tax_amount and tax.tax_amount != 0 %}
      <tr>
        <td>{{ tax.description }} <small>({{ tax.rate }}%)</small></td>
        <td>{{ frappe.utils.fmt_money(tax.tax_amount, currency=doc.currency) }}</td>
      </tr>
      {%- endif %}
      {%- endfor %}
      <tr class="grand-total-row">
        <td>الإجمالي <small>Grand Total</small></td>
        <td>{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td>
      </tr>
      {%- if doc.currency != company.default_currency and doc.base_grand_total %}
      <tr>
        <td>الإجمالي (محلي) <small>Base Total</small></td>
        <td>{{ frappe.utils.fmt_money(doc.base_grand_total, currency=company.default_currency) }}</td>
      </tr>
      {%- endif %}
    </table>
  </div>

  <!-- TERMS -->
  {%- if doc.terms %}
  <div class="terms-section">
    <div class="label">الشروط والأحكام <span class="en">/ Terms and Conditions</span></div>
    <div>{{ doc.terms }}</div>
  </div>
  {%- endif %}

  <!-- FOOTER -->
  <div class="footer">
    {{ doc.company }} &mdash; {{ doc.company_address or '' }}
  </div>

</div>
</body>
</html>
